CREATE COLUMN TABLE "TEST_AP"."OGDP" ("AbsEntry" INTEGER CS_INT NOT NULL , "RunName" NVARCHAR(100) NOT NULL , "RunDate" LONGDATE CS_LONGDATE, "Status" NVARCHAR(1) DEFAULT 'S', "UserSign" SMALLINT CS_INT, "UserSign2" SMALLINT CS_INT, "CreateDate" LONGDATE CS_LONGDATE, "CreateTS" INTEGER CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "UpdateTS" INTEGER CS_INT, "Action" NVARCHAR(1) DEFAULT 'R', "BPType" NVARCHAR(1) DEFAULT 'B', "PostDateTo" LONGDATE CS_LONGDATE, "EmpType" NVARCHAR(1) DEFAULT 'E', PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OGDP_SECONDARY" ON "TEST_AP"."OGDP" ( "RunName" ASC )